DATA={'source': '', 'request': '', 'authority': '', 'go': ''}
PINS={'payload': '7d1df28da31d3f3bd6c9dab7d9de3a98bef8291730a2bed7c28e8b1f1fa979f8', 'request': '9d6405c1e7a2a10d1073e08f52756edc26a2af1a37b14f6ebbf5d15462c134a6', 'authority': '3742c577ad96e0ea238cd20f804b1e8110bef337982e7395e1209999cfa38443', 'go': '5caa5f49b4598545b7f789907a4a868b1f316116442aad679701ba2f38098074'}

import base64,hashlib,json,sys,types,re
result=None
exit_code=1
try:
    raw={k:base64.b64decode(v,validate=True) for k,v in DATA.items()}
    if hashlib.sha256(raw['source']).hexdigest()!=PINS['payload']:
        raise ValueError('STDIN_SOURCE_PIN')
    for key in ('request','authority','go'):
        if hashlib.sha256(raw[key]).hexdigest()!=PINS[key]:
            raise ValueError('STDIN_DOCUMENT_PIN')
    module=types.ModuleType('_pinned_supervisor_hostfacts')
    sys.modules[module.__name__]=module
    exec(compile(raw['source'],'<pinned-supervisor-hostfacts>','exec'),module.__dict__)
    result=module.observe(raw['request'],raw['authority'],raw['go'],pins=module.Pins(**PINS),
                          payload_bytes=raw['source'])
    exit_code=0 if result.get('status')=='METADATA_ONLY_REQUIRES_REVIEW' else 2
except Exception as error:
    code=str(error) if isinstance(error,ValueError) and re.fullmatch('[A-Z][A-Z0-9_]{0,79}',str(error)) else 'STDIN_EXECUTION_REFUSED'
    result={'schema':'READONLY_SUPERVISOR_HOSTFACTS_STDIN_RESULT_V1','status':'REFUSED','code':code,'source_mutation':False}
encoded=json.dumps(result,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
if len(encoded)>4*1024*1024:
    encoded=b'{"status":"REFUSED","code":"STDIN_RESULT_LIMIT"}';exit_code=1
sys.stdout.buffer.write(encoded+b'\n')
raise SystemExit(exit_code)
